package com.ruoyi.system.service.impl;
import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.domain.shop.MallCoupon; import com.ruoyi.system.mapper.shop.MallCouponMapper; import com.ruoyi.system.service.IMallCouponService;
@Service public class MallCouponServiceImpl implements IMallCouponService { @Autowired private MallCouponMapper mapper; public List<MallCoupon> selectCouponList(MallCoupon c){return mapper.selectCouponList(c);} public MallCoupon selectCouponById(Long id){return mapper.selectCouponById(id);} public int insertCoupon(MallCoupon c){c.setReceivedQuantity(0L);c.setUsedQuantity(0L);validate(c);return mapper.insertCoupon(c);} public int updateCoupon(MallCoupon c){MallCoupon old=selectCouponById(c.getCouponId());if(old==null)throw new ServiceException("优惠券不存在");if(old.getReceivedQuantity()>0)throw new ServiceException("已被领取的优惠券不能修改规则");c.setReceivedQuantity(old.getReceivedQuantity());c.setUsedQuantity(old.getUsedQuantity());validate(c);return mapper.updateCoupon(c);} public int updateStatus(Long id,String s,String u){if(!"0".equals(s)&&!"1".equals(s))throw new ServiceException("优惠券状态非法");MallCoupon c=selectCouponById(id);if(c==null)throw new ServiceException("优惠券不存在");c.setStatus(s);c.setUpdateBy(u);return mapper.updateCouponStatus(c);} public int deleteCoupon(Long id){MallCoupon c=selectCouponById(id);if(c==null)throw new ServiceException("优惠券不存在");if(c.getReceivedQuantity()>0)throw new ServiceException("已被领取的优惠券不能删除");return mapper.deleteCouponById(id);} private void validate(MallCoupon c){if(c.getCouponName()==null||c.getCouponName().trim().isEmpty()||c.getThresholdAmount()==null||c.getDiscountAmount()==null||c.getTotalQuantity()==null||c.getLimitPerMember()==null)throw new ServiceException("优惠券必填字段不完整");if(c.getThresholdAmount()<0||c.getDiscountAmount()<0||c.getDiscountAmount()>c.getThresholdAmount()||c.getTotalQuantity()<1||c.getLimitPerMember()<1)throw new ServiceException("优惠券金额或数量非法");if(c.getReceiveBeginTime()==null||c.getReceiveEndTime()==null||!c.getReceiveBeginTime().before(c.getReceiveEndTime()))throw new ServiceException("领取时间窗口非法");if(c.getValidDays()!=null){if(c.getValidDays()<1||c.getValidBeginTime()!=null||c.getValidEndTime()!=null)throw new ServiceException("领取后有效期配置非法");}else if(c.getValidBeginTime()==null||c.getValidEndTime()==null||!c.getValidBeginTime().before(c.getValidEndTime()))throw new ServiceException("固定有效期配置非法");} }
